import base64, io, json, re, glob, html
from pathlib import Path
from PIL import Image

ROOT = Path(__file__).resolve().parents[2]
WEB = json.load(open(ROOT / ".claude/quiz-research/screens.json"))
WEB_BY_N = {e["n"]: e for e in WEB}
APP_DIR = ROOT / ".claude/competitor-teardown/betterme/screens"
OUT = Path(__file__).resolve().parent

def web_img(n):
    e = WEB_BY_N[n]
    m = re.match(r"data:image/(\w+);base64,(.*)", e["src"], re.S)
    return Image.open(io.BytesIO(base64.b64decode(m.group(2)))).convert("RGB"), e

def app_img(code):
    fs = sorted(glob.glob(str(APP_DIR / f"{code}*.png")))
    if not fs:
        raise SystemExit(f"missing app screen {code}")
    return Image.open(fs[0]).convert("RGB"), Path(fs[0]).stem

def data_uri(im, q=80):
    b = io.BytesIO(); im.save(b, "JPEG", quality=q, optimize=True)
    return "data:image/jpeg;base64," + base64.b64encode(b.getvalue()).decode()

