def render_ref(ref):
    kind = ref[0]
    if kind == "none":
        return f'<figure class="ref none"><div class="frame"><span>No BetterMe equivalent</span></div><figcaption>{html.escape(ref[1])}</figcaption></figure>'
    if kind == "web":
        im, e = web_img(ref[1])
        label = f"BetterMe web · {e['n']:02d} {e['title']}"
        return f'<figure class="ref"><div class="frame"><img src="{data_uri(im, 82)}" alt="{html.escape(label)}" loading="lazy" width="{im.width}" height="{im.height}"></div><figcaption><b>{html.escape(label)}</b>{html.escape(ref[2])}</figcaption></figure>'
    if kind == "webslice":
        n, a, b = ref[1]
        im, e = web_img(n)
        h = im.height; crop = im.crop((0, int(h*a), im.width, int(h*b)))
        label = f"BetterMe web · 55 The paywall, {int(a*100)}–{int(b*100)}% down"
        return f'<figure class="ref tall"><div class="frame"><img src="{data_uri(crop, 82)}" alt="{html.escape(label)}" loading="lazy" width="{crop.width}" height="{crop.height}"></div><figcaption><b>{html.escape(label)}</b>{html.escape(ref[2])}</figcaption></figure>'
    if kind == "app":
        im, stem = app_img(ref[1])
        label = f"BetterMe app · {stem} {APP_TITLES.get(ref[1], '')}".strip()
        return f'<figure class="ref"><div class="frame"><img src="{data_uri(im, 80)}" alt="{html.escape(label)}" loading="lazy" width="{im.width}" height="{im.height}"></div><figcaption><b>{html.escape(label)}</b>{html.escape(ref[2])}</figcaption></figure>'
    raise ValueError(kind)

