  "content": "/**
 * The arithmetic behind the belly branch of the quiz.
 *
 * Height, weight and goal weight come in from `b2-1` / `b2-2` / `b2-3`; pace from
 * `b5-1`; an optional event date from `b5-4`. From those the page draws a BMI
 * readout, a profile gauge, a with/without chart and a dated trajectory. The
 * same functions run server-side when the prescription needs them.
 *
 * The page carries a verbatim copy of this file inside
 * `<script id="fs-belly-math">` in `static-src/quiz/index.html`, because the
 * quiz is a single static document with no bundler. `belly-math.parity.test.ts`
 * executes that copy and checks it against this module, so the two cannot
 * drift silently. Change this file, then paste it into the page.
 *
 * Rules the numbers obey (see `.claude/quiz-belly/proposal.md` §Guardrails):
 *  - loss rate is 0.25 kg/week (steady) or 0.5 kg/week (moderate, fast) and never more;
 *  - a trajectory is a straight line from today to the goal date and is never bent
 *    to land before an event; if the event comes first, we report how far she gets;
 *  - the "without" line drifts up at the average mid-life gain, ~0.5 kg a year.
 */

export type Pace = "steady" | "moderate" | "fast";

export const RATE_KG_PER_WEEK: Record<Pace, number> = {
  steady: 0.25,
  moderate: 0.5,
  fast: 0.5,
};

/** Average weight gain through the transition, kg per year, for the "without" line. */
export const DRIFT_KG_PER_YEAR = 0.5;

export const LIMITS = {
  heightCm: { min: 120, max: 220 },
  weightKg: { min: 35, max: 200 },
};

// ---------------------------------------------------------------- units

export function cmFromFtIn(ft: number, inches: number): number {
  return round1((ft * 12 + inches) * 2.54);
}

export function ftInFromCm(cm: number): { ft: number; in: number } {
  const totalIn = Math.round(cm / 2.54);
  return { ft: Math.floor(totalIn / 12), in: totalIn % 12 };
}

export function kgFromLb(lb: number): number {
  return round1(lb * 0.45359237);
}

export function lbFromKg(kg: number): number {
  return round1(kg / 0.45359237);
}

// ---------------------------------------------------------------- bmi

export function bmi(kg: number, cm: number): number {
  const m = cm / 100;
  return round1(kg / (m * m));
}

export type BmiBandKey = "under" | "healthy" | "above" | "well-above";

export interface BmiBand {
  key: BmiBandKey;
  /** Copy shown beside the number. Never a diagnosis word. */
  label: string;
  /** Lower edge of the band on the gauge (inclusive). */
  from: number;
  /** Upper edge (exclusive), Infinity for the last band. */
  to: number;
}

export const BMI_BANDS: BmiBand[] = [
  { key: "under", label: "below the healthy range", from: 0, to: 18.5 },
  { key: "healthy", label: "in the healthy range", from: 18.5, to: 25 },
  { key: "above", label: "above the healthy range", from: 25, to: 30 },
  { key: "well-above", label: "well above the healthy range", from: 30, to: Infinity },
];

export function bmiBand(value: number): BmiBand {
  for (const band of BMI_BANDS) if (value < band.to) return band;
  return BMI_BANDS[BMI_BANDS.length - 1];
}

/** Position of a BMI on a gauge that runs 15 → 40, clamped, as a 0–1 fraction. */
export function gaugeFraction(value: number): number {
  const lo = 15;
  const hi = 40;
  return Math.min(1, Math.max(0, (value - lo) / (hi - lo)));
}

// ---------------------------------------------------------------- validation

export function validHeightCm(cm: number): boolean {
  return Number.isFinite(cm) && cm >= LIMITS.heightCm.min && cm <= LIMITS.heightCm.max;
}

export function validWeightKg(kg: number): boolean {
  return Number.isFinite(kg) && kg >= LIMITS.weightKg.min && kg <= LIMITS.weightKg.max;
}

/** A goal must sit below the current weight and above the floor. */
export function validGoalKg(goalKg: number, currentKg: number): boolean {
  return validWeightKg(goalKg) && goalKg < currentKg;
}

// ---------------------------------------------------------------- goal + timeline

export function gapKg(currentKg: number, goalKg: number): number {
  return round1(Math.max(0, currentKg - goalKg));
}

export function gapPercent(currentKg: number, goalKg: number): number {
  if (currentKg <= 0) return 0;
  return Math.round((gapKg(currentKg, goalKg) / currentKg) * 100);
}

export function weeksToGoal(gap: number, pace: Pace): number {
  if (gap <= 0) return 0;
  return Math.ceil(gap / RATE_KG_PER_WEEK[pace]);
}

/** Before a pace is chosen: the fastest and slowest honest estimates. */
export function weeksRange(gap: number): { min: number; max: number } {
  return { min: weeksToGoal(gap, "moderate"), max: weeksToGoal(gap, "steady") };
}

export function addWeeks(date: Date, weeks: number): Date {
  const d = new Date(date.getTime());
  d.setDate(d.getDate() + weeks * 7);
  return d;
}

export function weeksBetween(from: Date, to: Date): number {
  return (to.getTime() - from.getTime()) / (7 * 24 * 3600 * 1000);
}

export interface TrajectoryPoint {
  week: number;
  kg: number;
  date: Date;
}

/**
 * Weekly points from `start` at `currentKg` down to `goalKg`, at the pace's rate.
 * Straight line; the last point is exactly the goal on the goal date.
 */
export function trajectory(
  currentKg: number,
  goalKg: number,
  pace: Pace,
  start: Date,
): TrajectoryPoint[] {
  const gap = gapKg(currentKg, goalKg);
  const weeks = weeksToGoal(gap, pace);
  const pts: TrajectoryPoint[] = [];
  for (let w = 0; w <= weeks; w++) {
    const kg = weeks === 0 ? currentKg : round1(currentKg - (gap * w) / weeks);
    pts.push({ week: w, kg, date: addWeeks(start, w) });
  }
  return pts;
}

/** The "without" line: gentle upward drift over the same span. */
export function driftLine(currentKg: number, weeks: number, start: Date): TrajectoryPoint[] {
  const pts: TrajectoryPoint[] = [];
  for (let w = 0; w <= weeks; w++) {
    pts.push({
      week: w,
      kg: round1(currentKg + (DRIFT_KG_PER_YEAR * w) / 52),
      date: addWeeks(start, w),
    });
  }
  return pts;
}

export interface EventProgress {
  /** Does the goal date fall on or before the event? */
  reachedByEvent: boolean;
  /** Kilos lost by the event date, capped at the gap. */
  kgByEvent: number;
  /** Whole weeks from start to event, floored at 0. */
  weeksToEvent: number;
  goalDate: Date;
}

/**
 * Where she would be on the event date, on the honest line. The line is never
 * bent to land early: if the event comes before the goal date, `kgByEvent` is
 * simply the linear progress at that week.
 */
export function eventProgress(
  currentKg: number,
  goalKg: number,
  pace: Pace,
  start: Date,
  event: Date,
): EventProgress {
  const gap = gapKg(currentKg, goalKg);
  const weeks = weeksToGoal(gap, pace);
  const goalDate = addWeeks(start, weeks);
  const weeksToEvent = Math.max(0, Math.floor(weeksBetween(start, event)));
  const rate = RATE_KG_PER_WEEK[pace];
  const kgByEvent = round1(Math.min(gap, weeksToEvent * rate));
  return { reachedByEvent: goalDate.getTime() <= event.getTime(), kgByEvent, weeksToEvent, goalDate };
}

// ---------------------------------------------------------------- copy helpers

const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

/** "14 October" style, no year. */
export function shortDate(d: Date): string {
  return `${d.getDate()} ${MONTHS[d.getMonth()]}`;
}

/** "October 2026" style for the month picker and the trajectory axis. */
export function monthYear(d: Date): string {
  return `${MONTHS[d.getMonth()]} ${d.getFullYear()}`;
}

export function round1(n: number): number {
  return Math.round(n * 10) / 10;
}
