import type { Emphasis } from "@/content/types";
import type { StoredQuizProfile } from "@/db/schema";
import { programTemplateFor, type ProgramTemplate } from "@/content/templates";

/**
 * The Prescription compiler.
 *
 * One pure, deterministic function from a stored quiz sitting (answers +
 * profile) to the plan we prescribe — consumed by the paywall renderer, by
 * purchase-time program filling, and by the transformation-photo selector.
 * The rules are documented in `.claude/brainstorm/prescription-rules-v1.md`
 * (to be promoted to docs/); this file is their executable form. If you change
 * a rule here, change the document in the same commit.
 *
 * Division of trust: the *profile* (scores, ranking, mode) is the quiz's
 * scored artifact of record and is taken as given; *bands* and *guards* are
 * re-read from the raw answers, because they map 1:1 to single options and
 * the answers are the primary record.
 */

export type Band = 1 | 2 | 3 | 4;
export type Mode = "confirm" | "reconcile" | "weight" | "maintain" | "none";
export type GuardId =
  | "bones"
  | "joint"
  | "back"
  | "heart"
  | "recovery"
  | "dizziness"
  | "pelvic_floor";

export interface PrescriptionChip {
  label: string;
  lead: boolean;
}

export interface PrescriptionBlock {
  weeks: "1–2" | "3–4" | "5–8" | "9–12";
  title: string;
  chips: PrescriptionChip[];
  body: string;
  /** "Because you said…" / "Because of your back…" — null when nothing applies. */
  callout: string | null;
  /** The line drawn after the block (retest gates). Null on the last block. */
  gate: string | null;
}

export interface Prescription {
  version: 1;
  /** True when there was no scored profile and this is the generic rendering. */
  generic?: true;
  lead: Emphasis;
  goal: Emphasis | null;
  mode: Mode;
  /** Who leads the weekly sessions in weeks 3–4 (the reconcile doctrine's output). */
  sessionLead: Emphasis;
  /** The scored primary emphasis shown in the paywall's Now/After outcome. */
  outcomeEmphasis: Emphasis;
  /**
   * The machine-readable arc: which emphasis's template period fills each
   * stretch. This is what purchase-time filling consumes, and it is derived
   * from the same variables that titled the paywall blocks — the two cannot
   * disagree.
   */
  arc: { w34: Emphasis; w58: Emphasis; w912: Emphasis };
  /** The axis living in the daily slot when it lost the lead decision. */
  dailyFocus: Emphasis | null;
  bands: Partial<Record<Emphasis, Band>>;
  guards: GuardId[];
  entry: { reps: number; rounds: number; support: string };
  intro: string;
  daily: string;
  /** The transformation card's before/after feeling quotes — three pairs,
      keyed to the scored primary emphasis. */
  feel: { now: string; after: string }[];
  blocks: PrescriptionBlock[];
  /** Which of her answers drove which choice — renders the callouts, aids debugging. */
  evidence: Record<string, string>;
}

/* ------------------------------------------------------------------ inputs */

const EMPHASES: Emphasis[] = ["mobility", "balance", "strength", "energy"];

/**
 * The four checks, options ordered best → worst exactly as the quiz screens
 * list them. Answers are stored as this option text; stale cached pages may
 * still send bare indexes as digit strings.
 */
/* `question` is the screen's own wording, carried so a callout can name what
   she was answering. "Because you said “Not really”" is ambiguous on its own —
   she answered four of these, and the quote alone does not say which. */
const CHECKS: Record<Emphasis, { screen: string; question: string; options: string[] }> = {
  mobility: {
    screen: "s2-2",
    question: "Can you get up from the floor without using your hands?",
    options: [
      "Yes, easily",
      "Yes, but it takes effort",
      "I need a hand, or something to push off",
      "I avoid getting down there",
    ],
  },
  strength: {
    screen: "s2-3",
    question: "Can you carry shopping up a flight of stairs without stopping?",
    options: [
      "Yes, no problem",
      "Yes, but I'm puffed at the top",
      "I need to stop partway",
      "I avoid stairs with anything heavy",
    ],
  },
  balance: {
    screen: "s2-4",
    question: "Can you stand on one leg for 10 seconds?",
    options: ["Yes, either leg", "A few seconds", "Not really", "I've never tried"],
  },
  energy: {
    screen: "s2-5",
    question: "By mid-afternoon, how do you usually feel?",
    options: ["Still going", "Flagging, but fine", "I need to sit down", "I'm done by then"],
  },
};

const GUARD_OPTIONS: Record<string, GuardId> = {
  "Osteoporosis or osteopenia": "bones",
  "A joint replacement": "joint",
  "Back or neck problems": "back",
  "A heart condition or high blood pressure": "heart",
  "Recent surgery or an injury": "recovery",
  "Dizziness or balance problems": "dizziness",
};

/** Loose label match: case- and punctuation-insensitive. */
function norm(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9 ]/g, "").replace(/\s+/g, " ").trim();
}

/**
 * Her answer on one axis's check as its canonical option TEXT.
 *
 * Stale cached quiz pages stored bare option indexes as digit strings, and
 * quoting “2” back at her ("Because you said…") is worse than
 * no quote at all — so digits translate through the option list, and matched
 * text returns the canonical spelling.
 */
/**
 * "Because you said “X” to “Q” — so we Z."
 *
 * Three parts, all load-bearing. The quote is her own words. The question
 * disambiguates them — she answers four of these checks, and a bare “Not
 * really” could belong to any of them. The tail is what we do about it, and it
 * is what turns the callout from evidence into a prescription: without it the
 * line tells her we were listening but not what we changed. `tail` is required
 * rather than defaulted for that reason — a callout that forgets the "so we"
 * half should fail to compile, not ship silently.
 */
function becauseYouSaid(emphasis: Emphasis, said: string, tail: string): string {
  return (
    "Because you said \u201C" + said + "\u201D to \u201C" +
    CHECKS[emphasis].question + "\u201D \u2014 " + tail + "."
  );
}

export function checkAnswerText(
  answers: Record<string, string[]>,
  emphasis: Emphasis,
): string | null {
  const raw = answers[CHECKS[emphasis].screen]?.[0];
  if (raw === undefined) return null;
  const opts = CHECKS[emphasis].options;
  const matched = opts.find((o) => norm(o) === norm(raw));
  if (matched) return matched;
  if (/^\d+$/.test(raw.trim())) return opts[Number(raw.trim())] ?? null;
  return raw;
}

/** Her band on one axis's check: 4 = best rung, 1 = worst. Null if unanswered. */
export function bandFor(
  answers: Record<string, string[]>,
  emphasis: Emphasis,
): Band | null {
  const check = CHECKS[emphasis];
  const picked = answers[check.screen]?.[0];
  if (picked === undefined) return null;
  let index = check.options.findIndex((o) => norm(o) === norm(picked));
  if (index === -1 && /^\d+$/.test(picked.trim())) {
    index = Number(picked.trim());
  }
  if (index < 0 || index > 3) return null;
  return (4 - index) as Band;
}

function guardsFrom(answers: Record<string, string[]>): GuardId[] {
  const out: GuardId[] = [];
  for (const picked of answers["s2-10"] ?? []) {
    const id = GUARD_OPTIONS[Object.keys(GUARD_OPTIONS).find((k) => norm(k) === norm(picked)) ?? ""];
    if (id && !out.includes(id)) out.push(id);
  }
  const leak = answers["s2-8"]?.[0];
  if (leak !== undefined && norm(leak) !== norm("Never") && leak.trim() !== "0") {
    out.push("pelvic_floor");
  }
  return out;
}

/* ------------------------------------------------------------------- rules */

/**
 * The dependency graph (design principle 1 + §2.1): which needs sit upstream
 * of which goals, with the bridge line that makes the order sayable.
 * Mobility is upstream of everything; strength of balance and energy;
 * balance and energy of nothing.
 */
const BRIDGE: Partial<Record<Emphasis, Partial<Record<Emphasis, string>>>> = {
  mobility: {
    strength:
      "Your strength plan starts in your hips — stiffness is what's been making everything feel heavier. Range first, then load.",
    balance:
      "Your balance plan starts in your ankles and hips — steadiness needs range before it needs practice.",
    energy:
      "Your energy plan starts in your hips — stiff movement is expensive movement. Range first, then capacity.",
  },
  strength: {
    balance: "Your balance plan starts with the muscles that catch you — strength first, then steadiness.",
    energy:
      "Your energy plan starts with muscle — the afternoon dip is a capacity problem, and capacity is muscle.",
  },
};

const NAMES: Record<Emphasis, string> = {
  mobility: "Mobility",
  balance: "Balance",
  strength: "Strength",
  energy: "Energy",
};

/** What the lead's daily micro-dose looks like, for the daily line. */
const DAILY_MICRO: Record<Emphasis, string> = {
  mobility: "hip and back openers",
  balance: "balance holds at the counter",
  strength: "sit-to-stand practice",
  energy: "a brisk couple of minutes on your feet",
};

const GUARD_CALLOUT: Partial<Record<GuardId, string>> = {
  back: "Because of your back: no floor work yet, and no loaded bending at any point.",
  bones:
    "Because of your bones: we load you — bone likes load — but never bent or twisted under it.",
  joint: "Because of your joint replacement: we stay away from that joint's end range.",
  heart:
    "Because of your heart: intensity builds slowly and stays steady — never a breath held.",
  recovery: "Because you're recovering: we start you below where you think you should be.",
  dizziness: "Because of the dizziness: every balance move keeps a hand on support.",
};

/** Priority when several guards could take the opening callout. */
const GUARD_PRIORITY: GuardId[] = ["back", "bones", "joint", "heart", "recovery", "dizziness"];

const DOSE: Record<Band, { reps: number; rounds: number; support: string }> = {
  1: { reps: 5, rounds: 2, support: "always in reach, used freely" },
  2: { reps: 6, rounds: 3, support: "in reach" },
  3: { reps: 8, rounds: 3, support: "nearby" },
  4: { reps: 8, rounds: 3, support: "none — household load joins in" },
};

const W58_BODY: Record<Emphasis, string> = {
  balance:
    "Balance keeps the lead; strength joins underneath it — steadiness that survives a conversation, a full kettle, a grandchild on your hip.",
  strength:
    "Household load, step-ups, slow lowers — strength built through the range you've opened.",
  mobility: "Strength through the new range — deeper sit-to-stands, reaches under light load.",
  energy: "Rounds grow and rest falls — capacity you can feel by teatime.",
};

/**
 * The "— so we …" half of a callout, per block and per axis.
 *
 * Each line must describe what that block genuinely does, because it sits
 * directly under the block's own body and gate: weeks 3–4 paraphrase the
 * template's week-3 summary, weeks 5–8 paraphrase W58_BODY. If the programme
 * content changes, these change with it — a prescription that no longer matches
 * the programme underneath it is worse than no callout, since she is being
 * asked to pay on the strength of exactly this correspondence.
 *
 * Weeks 1–2 only ever cite mobility (the opening block is the range-opener for
 * everyone), so it carries one entry rather than four.
 */
const CALLOUT_TAIL: {
  w12: Partial<Record<Emphasis, string>>;
  w34: Record<Emphasis, string>;
  w58: Record<Emphasis, string>;
} = {
  w12: { mobility: "so we open the range first" },
  w34: {
    mobility: "so we go deeper, with the chair under both hands",
    balance: "so the support comes away before the task gets harder",
    strength: "so we drop the seat and let household load do the work",
    energy: "so it runs as one circuit and the rest starts falling",
  },
  w58: {
    mobility: "so we build strength through the range you've opened",
    balance: "so balance keeps the lead, with strength underneath it",
    strength: "so we add weight and keep the range",
    energy: "so the rounds grow while the rest keeps falling",
  },
};

/** "…from ‘her answer’ to <this>" — the final block's destination phrasing. */
const TARGET_TO: Record<Emphasis, string> = {
  balance: "ten seconds, unsupported, either side",
  strength: "up with the shopping, no stop",
  mobility: "down to the floor and back up, unaided",
  energy: "still going by mid-afternoon",
};

/** The transformation card's felt before/after, per emphasis. Function, not a
    body: each pair is a daily moment she recognises and its week-12 version. */
const FEEL: Record<Emphasis, { now: string; after: string }[]> = {
  balance: [
    { now: "I hold the banister without noticing.", after: "I stopped holding the banister." },
    { now: "Getting off the floor needs both hands.", after: "Up off the floor, no hands." },
    { now: "Curbs make me careful.", after: "Ten seconds on one leg. Either side." },
  ],
  mobility: [
    { now: "Mornings start stiff and slow.", after: "Mornings just start." },
    { now: "Getting down to the floor is a project.", after: "Down and back up, unaided." },
    { now: "High shelves mean the step stool.", after: "The back of the shelf, no twinge." },
  ],
  strength: [
    { now: "Shopping goes up in two trips.", after: "One trip, no stop at the top." },
    { now: "Out of a chair means pushing off.", after: "Up without using my hands." },
    { now: "Heavy days leave me sore.", after: "It didn't hurt the next day." },
  ],
  energy: [
    { now: "By three o'clock I'm done.", after: "The afternoon stopped being a cliff." },
    { now: "Stairs leave me puffed.", after: "Still going at the top." },
    { now: "I plan my day around my energy.", after: "A full day on my feet." },
  ],
};

/** Weeks 5–8 and 9–12 theme titles come from the real programme templates. */
function themeTitles(emphasis: Emphasis): { w58: string; w912: string; week3Summary: string } {
  const periods = programTemplateFor(emphasis).periods;
  return { w58: periods[4].name, w912: periods[5].name, week3Summary: periods[2].summary };
}

/* ---------------------------------------------------------------- compiler */

export function compilePrescription(
  answers: Record<string, string[]>,
  profile: StoredQuizProfile | null,
): Prescription {
  const guards = guardsFrom(answers ?? {});
  const bands: Partial<Record<Emphasis, Band>> = {};
  for (const e of EMPHASES) {
    const b = bandFor(answers ?? {}, e);
    if (b !== null) bands[e] = b;
  }

  const primary = (profile?.primary ?? null) as Emphasis | null;
  if (!profile || !primary || !EMPHASES.includes(primary)) {
    return generic(bands, guards);
  }

  const goal = (profile.goalAxis ?? null) as Emphasis | null;
  const mode = (profile.mode ?? "none") as Mode;
  const secondary = ((profile.secondary ?? primary) as Emphasis) || primary;

  /*
   * Safety override: an untrained balance (band 1) or a dizziness guard puts
   * balance first no matter what she asked for — fall risk gates everything,
   * and that sentence is easy to say honestly.
   */
  const unsafeBalance = bands.balance === 1 || guards.includes("dizziness");

  let lead: Emphasis = mode === "maintain" ? (goal ?? primary) : primary;
  let sessionLead: Emphasis = lead;
  let dailyFocus: Emphasis | null = null;
  let bridge: string | null = null;
  let earlyHandover = false; // reconcile-✦ only: goal may take over at week 4
  const narrativeLead: Emphasis = goal ?? lead; // whose milestone titles the ending

  if (unsafeBalance && lead !== "balance") {
    bridge =
      "Steadiness comes first — before anything else, we make you safe on your feet. Then " +
      NAMES[narrativeLead].toLowerCase() +
      " gets its turn.";
    lead = "balance";
    sessionLead = "balance";
    earlyHandover = false;
  } else if (mode === "reconcile" && goal && goal !== lead) {
    const upstream = BRIDGE[lead]?.[goal] ?? null;
    if (upstream) {
      // ✦ the need is on the path to her goal: it leads, the goal takes over at W5.
      bridge = upstream;
      sessionLead = lead;
      earlyHandover = true;
    } else {
      // ○ it isn't: her goal leads, the need moves into the daily slot.
      sessionLead = goal;
      dailyFocus = lead;
    }
  }

  /* Entry dose from the session lead's band (recovery shifts one band down). */
  let entryBand: Band = bands[sessionLead] ?? 2;
  if (guards.includes("recovery")) entryBand = Math.max(1, entryBand - 1) as Band;
  const entry = DOSE[entryBand];

  /* The intro line above the blocks. */
  let intro: string;
  const suffix = " That order comes from your answers, not a template.";
  if (bridge) {
    intro = bridge + suffix;
  } else if (mode === "weight") {
    intro =
      NAMES[lead] +
      " leads, with strength and energy close behind — shape follows muscle, and muscle is the most reversible thing on your list.";
  } else if (mode === "maintain") {
    intro =
      "Nothing here is in trouble — this plan is about keeping it that way, and going a little further than you would alone.";
  } else if (dailyFocus) {
    intro =
      NAMES[sessionLead] +
      " leads — and your " +
      NAMES[dailyFocus].toLowerCase() +
      " gets five quiet minutes every single day alongside it." +
      suffix;
  } else if (lead === "mobility") {
    intro = "Mobility leads — it's the foundation strength, balance and energy all stand on." + suffix;
  } else {
    intro =
      NAMES[lead] + " leads — mobility opens the way first, strength backs it up." + suffix;
  }

  /* The daily line (principle: the daily slot is the bigger cumulative dose). */
  const dailyBits: string[] = [DAILY_MICRO[dailyFocus ?? sessionLead]];
  if (guards.includes("pelvic_floor")) dailyBits.push("pelvic floor work");
  const daily = "Five minutes every morning — the wake-up routine, with " + dailyBits.join(" and ") + ".";

  /* Evidence: the answers each choice cites. */
  const evidence: Record<string, string> = {};
  for (const e of EMPHASES) {
    const a = checkAnswerText(answers ?? {}, e);
    if (a !== null) evidence[e] = a;
  }

  const guardId = GUARD_PRIORITY.find((g) => guards.includes(g)) ?? null;

  /* ---- the four blocks ---- */

  const w58Lead: Emphasis = earlyHandover && goal ? goal : sessionLead;
  const w58Support: Emphasis | null =
    mode === "weight" ? null : earlyHandover ? sessionLead : dailyFocus ?? secondary;
  const t = themeTitles(w58Lead);
  const ending = themeTitles(narrativeLead);

  const saidLead = evidence[sessionLead];

  const blocks: PrescriptionBlock[] = [
    {
      weeks: "1–2",
      title: "Loosen what's tight, build the base",
      chips: [
        { label: "Mobility", lead: true },
        { label: "Strength base", lead: false },
      ],
      body:
        "Hips and lower back first — opening the range everything else will use. Three short sessions a week, every movement filmed, chair right there.",
      callout: guardId
        ? (GUARD_CALLOUT[guardId] ?? null)
        : sessionLead !== "mobility" && evidence.mobility && (bands.mobility ?? 4) < 4
          ? becauseYouSaid("mobility", evidence.mobility, CALLOUT_TAIL.w12.mobility!)
          : null,
      gate: "Same moves in week 2, more of you in them.",
    },
    {
      weeks: "3–4",
      title:
        earlyHandover && goal
          ? NAMES[sessionLead] + " first — your " + NAMES[goal].toLowerCase() + " work begins inside it"
          : "Your " + NAMES[sessionLead].toLowerCase() + " work begins",
      chips: earlyHandover && goal
        ? [
            { label: NAMES[sessionLead] + " · the route", lead: true },
            { label: NAMES[goal] + " · your goal", lead: false },
          ]
        : [
            { label: NAMES[sessionLead] + " · your focus", lead: true },
            { label: NAMES[dailyFocus ?? secondary], lead: false },
          ],
      body: themeTitles(sessionLead).week3Summary + " Week 4 ends with your first check.",
      callout: saidLead
        ? becauseYouSaid(sessionLead, saidLead, CALLOUT_TAIL.w34[sessionLead])
        : null,
      gate:
        earlyHandover && goal
          ? "If your " + NAMES[sessionLead].toLowerCase() + " has opened up by week 4, " +
            NAMES[goal].toLowerCase() + " takes the lead early."
          : "Your week-4 numbers decide the mix of the next four weeks.",
    },
    {
      weeks: "5–8",
      title: t.w58,
      chips: [
        { label: NAMES[w58Lead], lead: true },
        w58Support
          ? { label: "+ " + NAMES[w58Support], lead: false }
          : { label: "+ Strength & Energy", lead: false },
      ],
      body: W58_BODY[w58Lead],
      callout:
        earlyHandover && goal
          ? "Because " + NAMES[goal].toLowerCase() + " is where you want to go: it takes the lead here."
          : w58Lead !== sessionLead && evidence[w58Lead]
            ? becauseYouSaid(w58Lead, evidence[w58Lead], CALLOUT_TAIL.w58[w58Lead])
            : null,
      gate: "Your week-8 check sets the final block.",
    },
    {
      weeks: "9–12",
      title: ending.w912,
      chips: [
        { label: NAMES[narrativeLead], lead: true },
        {
          label:
            NAMES[
              ([w58Support, sessionLead, "strength", "mobility"] as const)
                .filter((e): e is Emphasis => !!e)
                .find((e) => e !== narrativeLead) ?? "mobility"
            ],
          lead: false,
        },
      ],
      body:
        "Measured against your own first week, not a chart: from “" +
        (evidence[narrativeLead] ?? "where you are now") +
        "” to " +
        TARGET_TO[narrativeLead] +
        ".",
      callout: null,
      gate: null,
    },
  ];

  return {
    version: 1,
    lead,
    goal,
    mode,
    sessionLead,
    outcomeEmphasis: primary,
    arc: { w34: sessionLead, w58: w58Lead, w912: narrativeLead },
    dailyFocus,
    bands,
    guards,
    entry,
    intro,
    daily,
    feel: FEEL[primary],
    blocks,
    evidence,
  };
}

/** No scored profile: the generic mobility-led rendering, clearly marked. */
function generic(
  bands: Partial<Record<Emphasis, Band>>,
  guards: GuardId[],
): Prescription {
  const t = themeTitles("mobility");
  return {
    version: 1,
    generic: true,
    lead: "mobility",
    goal: null,
    mode: "none",
    sessionLead: "mobility",
    outcomeEmphasis: "mobility",
    arc: { w34: "mobility", w58: "mobility", w912: "mobility" },
    dailyFocus: null,
    bands,
