    entry: DOSE[2],
    intro:
      "Twelve weeks in three blocks — mobility first, strength throughout, and the later blocks rebuilt around your check-ins at weeks 4 and 8.",
    daily: "Five minutes every morning — the wake-up routine.",
    feel: FEEL.balance,
    blocks: [
      {
        weeks: "1–2",
