        chips: [{ label: "Mobility", lead: true }, { label: "Strength", lead: false }],
        body: "Measured against your own first week, not a chart.",
        callout: null,
        gate: null,
      },
    ],
    evidence: {},
  };
}

/* --------------------------------------------------- purchase-time filling */

/**
 * The programme template her purchase fills, assembled from the Prescription's
 * arc. Weeks 1–4 come from the session lead's template (the shared ramp plus
 * her path's weeks 3–4); weeks 5–8 and 9–12 take the themed periods of
 * whichever emphasis the paywall promised for those stretches. Because the arc
 * and the paywall block titles come from the same compiler variables, the plan
 * she bought reads exactly as the plan she was shown.
 */
export function templateFromPrescription(rx: Prescription): ProgramTemplate {
  const base = programTemplateFor(rx.arc.w34);
  return {
    slug: `rx-${rx.arc.w34}-${rx.arc.w58}-${rx.arc.w912}-12wk`,
    version: 1,
    periods: [
      base.periods[0],
      base.periods[1],
      base.periods[2],
      base.periods[3],
      programTemplateFor(rx.arc.w58).periods[4],
      programTemplateFor(rx.arc.w912).periods[5],
    ],
  };
}

