import { cookies } from "next/headers";
import { getDb } from "@/db/client";
import { saveQuizResponse, findQuizByPublicId, newPublicId } from "@/db/quiz";
import { compilePrescription } from "@/lib/prescription";
import { normaliseEmail } from "@/lib/email/address";

/**
 * Quiz storage endpoint.
 *
 * The quiz posts here as she answers and again when it finishes scoring. It is
 * called from an anonymous browser, before she is a customer and possibly
 * before she has decided to be one.
 */

/**
 * The funnel's thread.
 *
 * Issued on her first save and returned to the client, which keeps it in
 * localStorage and appends it to the checkout link. At purchase it is what
 * finds these answers again. Also mirrored into a cookie so a sitting survives
 * a page reload even if localStorage is cleared or blocked.
 */
export const QUIZ_COOKIE = "fs_quiz";
const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365;

/** Guards against a malformed or hostile body filling the table with junk. */
const MAX_ANSWERS = 200;

interface Body {
  publicId?: string;
  /** Option text per screen. Old cached quiz pages may still send numbers. */
  answers?: Record<string, (string | number)[]>;
  profile?: Record<string, unknown> | null;
  name?: string | null;
  email?: string | null;
  completed?: boolean;
}

/** One selected option, as stored: text, bounded. */
const MAX_ANSWER_CHARS = 200;

/**
 * Restores a sitting for a personalised link (`/quiz?pid=...`), typically
 * opened from an email in a different browser than the one that took the
 * quiz. Returns only what the paywall needs to render as hers — the name and
 * the compiled plan. Answers and email stay server-side: the id is a
 * correlation handle anyone could hold, so the response must be something we
 * would show on a shared screen, and checkout already reads her email from
 * the row by this same id.
 */
export async function GET(request: Request) {
  const pid = new URL(request.url).searchParams.get("pid")?.trim();
  if (!pid) return Response.json({ error: "pid required" }, { status: 400 });

  const row = await findQuizByPublicId(getDb(), pid);
  if (!row) return Response.json({ error: "Not found" }, { status: 404 });

  return Response.json(
    {
      publicId: row.publicId,
      name: row.name,
      completed: row.completedAt !== null,
      prescription: row.profile
        ? compilePrescription(row.answers, row.profile)
        : null,
    },
    { headers: { "cache-control": "private, no-store" } },
  );
}

export async function POST(request: Request) {
  let body: Body;
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const answers = body.answers ?? {};
  if (typeof answers !== "object" || Array.isArray(answers)) {
    return Response.json({ error: "answers must be an object" }, { status: 400 });
  }
  if (Object.keys(answers).length > MAX_ANSWERS) {
    return Response.json({ error: "Too many answers" }, { status: 400 });
  }

  /*
   * Stored as the text she chose, whatever arrives. The page sends option
   * labels; a stale cached copy of it still sends indexes, which become
   * digit-strings rather than a rejected sitting — losing her answers over a
   * cache would be a poor trade for purity.
   */
  const cleanAnswers: Record<string, string[]> = {};
  for (const [screen, picks] of Object.entries(answers)) {
    if (!Array.isArray(picks)) {
      return Response.json({ error: "answers values must be arrays" }, { status: 400 });
    }
    cleanAnswers[screen] = picks
      .filter((p): p is string | number => typeof p === "string" || typeof p === "number")
      .map((p) => String(p).slice(0, MAX_ANSWER_CHARS));
  }

  const jar = await cookies();
  // Trust the client's id if it has one, otherwise the cookie, otherwise mint.
  // The id is only a correlation handle, so accepting a client-supplied value
  // is safe — it grants no access on its own.
  const publicId =
    body.publicId?.trim() || jar.get(QUIZ_COOKIE)?.value || newPublicId();

  const row = await saveQuizResponse(getDb(), publicId, {
    answers: cleanAnswers,
    profile: (body.profile ?? null) as Parameters<
      typeof saveQuizResponse
    >[2]["profile"],
    name: typeof body.name === "string" ? body.name.trim().slice(0, 80) || null : null,
    /*
     * Dropped to null when it is not an address, never a 400. She is mid-quiz
     * and half-way through typing on a phone keyboard; refusing the whole save
     * would cost her the answers as well as the address, and the next save
     * carries a corrected one anyway.
     */
    email: normaliseEmail(body.email),
    completed: body.completed === true,
  });

  jar.set(QUIZ_COOKIE, publicId, {
    httpOnly: false, // the quiz page reads it to keep client and server in step
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: ONE_YEAR_SECONDS,
  });

  return Response.json({
    publicId: row.publicId,
    primaryEmphasis: row.primaryEmphasis,
    completed: row.completedAt !== null,
    /*
     * The compiled plan, from the row as saved — the paywall renders this
     * verbatim, and purchase fills from the same compiler, which is what keeps
     * "what she was shown" and "what she gets" the same object. Null until a
     * scored profile exists (the page keeps its generic rendering).
     */
    prescription: row.profile
      ? compilePrescription(row.answers, row.profile)
      : null,
  });
}
