import { describe, it, expect } from "vitest";
import { compilePrescription, bandFor } from "./prescription";
import type { StoredQuizProfile } from "@/db/schema";

/*
 * Personas exercise the rules in `.claude/brainstorm/prescription-rules-v1.md`:
 * confirm, reconcile (both cells), safety override, weight, maintain, guards,
 * legacy digit answers, and the no-profile fallback.
 */

/** Answers as the quiz stores them: option text per screen. */
function answers(over: Record<string, string[]> = {}): Record<string, string[]> {
  return {
    "s2-2": ["Yes, but it takes effort"], // floor  → mobility band 3
    "s2-3": ["Yes, no problem"], // stairs → strength band 4
    "s2-4": ["A few seconds"], // one leg → balance band 3? no — index 1 → band 3
    "s2-5": ["Still going"], // afternoon → energy band 4
    "s2-10": ["None of these"],
    ...over,
  };
}

function profile(over: Partial<StoredQuizProfile> = {}): StoredQuizProfile {
  return {
    scores: {
      mobility: { value: 55 },
      balance: { value: 40 },
      strength: { value: 70 },
      energy: { value: 65 },
    },
    ranked: ["balance", "mobility", "energy", "strength"],
    primary: "balance",
    secondary: "mobility",
    goalAxis: "balance",
    mode: "confirm",
    strongStart: false,
    answered: 10,
    ...over,
  } as StoredQuizProfile;
}

describe("band parsing", () => {
  it("maps option text to bands, best answer = band 4", () => {
    expect(bandFor({ "s2-4": ["Yes, either leg"] }, "balance")).toBe(4);
    expect(bandFor({ "s2-4": ["A few seconds"] }, "balance")).toBe(3);
    expect(bandFor({ "s2-4": ["Not really"] }, "balance")).toBe(2);
    expect(bandFor({ "s2-4": ["I've never tried"] }, "balance")).toBe(1);
  });

  it("tolerates legacy digit-string answers", () => {
    expect(bandFor({ "s2-4": ["3"] }, "balance")).toBe(1);
    expect(bandFor({ "s2-2": ["0"] }, "mobility")).toBe(4);
  });

  it("returns null when unanswered or unrecognised", () => {
    expect(bandFor({}, "balance")).toBeNull();
    expect(bandFor({ "s2-4": ["something else entirely"] }, "balance")).toBeNull();
  });
});

