/* ================================================================== *
 *  FSBelly — the belly branch of the quiz (goal option 0).
 *
 *  A branch, not a second quiz: the same `screens` array, walked by
 *  next() through shouldSkip(). When the goal is "lose weight, especially
 *  around my middle" the control screens listed in WEIGHT_SKIPS are skipped
 *  and the `s*-w*` screens are shown; for every other goal it is the other
 *  way round. Nothing here runs unless FSBelly.active().
 *
 *  Spec: .claude/feature/quiz-belly-branch.md. Math: FSBellyMath (the
 *  inlined copy of src/lib/belly-math.ts).
 * ================================================================== */
window.FSBelly = (function () {
  var M = window.FSBellyMath;
  var $ = function (sc, sel) { return sc.querySelector(sel); };
  var $$ = function (sc, sel) { return [].slice.call(sc.querySelectorAll(sel)); };
  var forced = /[?&]belly=0/.test(location.search);

  /* Control screens the branch does not visit. s5-5/s5-6 go too: the profile
     (s2-w4), the reveal (s2-w6) and the trajectory (s4-w8) have done that job. */
  var WEIGHT_SKIPS = {
    's1-5': 1, 's1-6': 1, 's2-2': 1, 's2-3': 1, 's2-4': 1, 's2-7': 1, 's2-8': 1, 's2-9': 1,
    's2-11': 1, 's3-1': 1, 's3-2': 1, 's3-3': 1, 's3-5': 1, 's3-6': 1, 's4-2': 1, 's4-3': 1,
    's5-5': 1, 's5-6': 1
  };
  var BRANCH_ID = /^s\d-w\d/;

  /* Act chrome for the branch: five acts, and the shared movement screens
     move from act 2 to act 3. Restored from data-orig when the branch is off. */
  var ACT = {
    's1-w1': [1, 'Your middle'], 's1-w2': [1, 'Your middle'], 's1-w3': [1, 'Your middle'], 's1-w4': [1, 'Your middle'], 's1-w5': [1, 'Your middle'],
    's2-w1': [2, 'Your numbers'], 's2-w2': [2, 'Your numbers'], 's2-w3': [2, 'Your numbers'], 's2-w4': [2, 'Your numbers'],
    's2-1': [3, 'How you move today'], 's2-5': [3, 'How you move today'], 's2-6': [3, 'How you move today'],
    's2-w5': [3, 'How you move today'], 's2-10': [3, 'How you move today'], 's2-w6': [3, 'How you move today'],
    's4-w1': [4, 'What’s in the way'], 's4-w2': [4, 'What’s in the way'], 's4-1': [4, 'What’s in the way'], 's4-w3': [4, 'What’s in the way'],
    's4-w4': [5, 'Pace and goal'], 's4-w5': [5, 'Pace and goal'], 's4-w6': [5, 'Pace and goal'], 's4-w7': [5, 'Pace and goal'], 's4-w8': [5, 'Pace and goal'],
    's4-4': [5, 'Almost there'], 's4-5': [5, 'Almost there']
  };

  function goal() { return window.FS ? FS.one('s1-4') : null; }
  function active() {
    if (forced) return false;
    var g = goal();
    if (g !== null) return g === 0;
    /* A restored sitting (?pid=) has no answers; the server's verdict stands in. */
    var rx = window.FSRX;
    return !!(rx && !rx.generic && rx.mode === 'weight');
  }
  function skips(id) { return active() ? !!WEIGHT_SKIPS[id] : BRANCH_ID.test(id); }
  function affects(id) { return !!WEIGHT_SKIPS[id] || BRANCH_ID.test(id); }

  /* ---------------------------------------------------------- figures */
