  "content": "import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { html } from "./quiz";

/*
 * The belly branch (`.claude/feature/quiz-belly-branch.md`): goal option 0 on
 * s1-4 diverts into `s*-w*` screens and back out to s5-7. These pins keep the
 * wiring honest without freezing copy.
 */

const SOURCE = readFileSync(new URL("../../static-src/quiz/index.html", import.meta.url), "utf8");

const ids = () => [...html.matchAll(/class="shotcard" id="([^"]+)"/g)].map((m) => m[1]);

describe("belly branch: screens", () => {
  it("is generated from the edited source", () => {
    expect(html).toBe(SOURCE);
  });

  it("puts every branch screen where the flow needs it", () => {
    const order = ids();
    const at = (id: string) => {
      const i = order.indexOf(id);
      expect(i, `${id} missing`).toBeGreaterThan(-1);
      return i;
    };
    // Act 1 sits right after the goal and before the control's s1-5.
    expect(at("s1-w1")).toBe(at("s1-4") + 1);
    expect(at("s1-w5")).toBeLessThan(at("s1-5"));
    // Numbers come before the shared movement screens.
    expect(at("s2-w4")).toBeLessThan(at("s2-1"));
    // The branch's sleep copy follows stiffness; the reveal follows the safety screen.
    expect(at("s2-w5")).toBe(at("s2-6") + 1);
    expect(at("s2-w6")).toBe(at("s2-10") + 1);
    // Motivation statements precede s4-1; the chart follows it; pacing precedes the name.
    expect(at("s4-w2")).toBe(at("s4-1") - 1);
    expect(at("s4-w3")).toBe(at("s4-1") + 1);
    expect(at("s4-w8")).toBe(at("s4-4") - 1);
    // Nineteen branch screens, all marked.
    expect((html.match(/data-branch="weight"/g) ?? []).length).toBe(19);
  });

  it("keeps the paywall on s5-7 and never adds a second outcome section to the markup", () => {
    expect(html).toContain("ids: ['s5-5', 's5-6', 's5-7']");
    expect((html.match(/data-fssection="outcome"/g) ?? []).length).toBe(1);
    expect(html).not.toContain('data-fssection="outcome-weight"');
    // the hero block is built at runtime, so the section-order tests stay true
    expect(html).toContain("block.id = 'fsbhero'");
  });
});

describe("belly branch: wiring", () => {
  it("skips through the one shared flow array", () => {
    expect(html).toContain("if (window.FSBelly && FSBelly.skips(card.id)) return true;");
    expect(html).toContain("'s5-5': 1, 's5-6': 1");
    expect(html).toContain("var BRANCH_ID = /^s\\d-w\\d/;");
  });

  it("records typed values on data-fsval and reports only a sanitised choice", () => {
    expect(html).toContain("var fv = $(sc, '[data-fsval]');");
    expect(html).toContain("var fc = sc.getAttribute('data-fschoice');");
    // every numeric screen stamps a summary, never the number
    expect(html).toContain("sc.setAttribute('data-fschoice', 'bmi ' + band.key);");
    expect(html).toContain("sc.setAttribute('data-fschoice', 'gap ' + pc + '%');");
    expect(html).toContain("sc.setAttribute('data-fschoice', p + ' ' + weeks + 'w');");
    // and nothing about her body reaches the pixel
    const pixel = html.slice(html.indexOf("window.FSTrack"), html.indexOf("window.FS ="));
    expect(pixel).not.toMatch(/bmi|weightKg|heightCm|FSBelly/);
  });

  it("gates Continue on the numeric screens and fires completion from s5-7 in the branch", () => {
    expect(html).toContain("if (window.FSBelly && !FSBelly.beforeNext(sc, btn)) return;");
    expect(html).toContain("if (screens[i].id === 's5-5') { completeQuiz(); }");
    expect(html).toContain("else if (screens[i].id === 's5-7' && window.FSBelly && FSBelly.active()) { completeQuiz(); }");
  });

  it("inlines the math module the parity test checks", () => {
    expect(html).toContain('<script id="fs-belly-math">');
    expect(html).toContain("window.FSBellyMath = (function () {");
  });
});
"
}

