/**
 * The plans she can choose on the paywall.
 *
 * Prices live in Stripe and are addressed by `lookupKey`, never by price id —
 * so test and live share this file, and changing a price is a Dashboard action
 * rather than a deploy.
 *
 * The amounts here are for *display only*. What she is actually charged always
 * comes from Stripe, resolved server-side at checkout, so a tampered client can
 * never buy at a price of its own choosing.
 *
 * Which means these numbers CAN drift from Stripe, and the drift is invisible:
 * the paywall would advertise one amount while Checkout charges another.
 * `plans.stripe.test.ts` is what catches that, and it needs a key —
 * `pnpm test:stripe`. Run it after changing any price in the Dashboard.
 */

/** `trial` is a way of paying for the same 12 weeks, not a different product:
 *  it defers the single charge by a free week and costs $10 more for the
 *  deferral. It needs its own id because the two-option paywall shows it
 *  alongside `twelve_week`, and the two resolve to different Stripe prices. */
export type PlanId = "weekly" | "four_weekly" | "twelve_week" | "trial";

export interface Plan {
  id: PlanId;
  lookupKey: string;
  /** Shown on the selector. */
  name: string;
  /** Display amount in minor units. Must match Stripe. */
  amountCents: number;
  /**
   * The price's base currency. Every plan also carries the same NUMBER in
   * euros — €49, not an FX-converted €45.31 — as a Stripe `currency_options`
   * entry on the same price object, so a single lookup key serves both and
   * there is no second catalogue to keep in step. `currencyFor()` picks which
   * one a visitor is quoted, from her country.
   */
  currency: "usd";
  /**
   * Amount in euro cents. Deliberately a separate number rather than a
   * conversion: the point of the experiment is the same figure in both
   * currencies, and a rate that moves would make two visitors in the same
   * arm see different prices.
   */
  amountEurCents: number;
  /** "a week", "a month", "every 12 weeks" — how it renews, in her words. */
  cadence: string;
  /** Effective weekly cost, for the value comparison. */
  perWeekCents: number;
  /** Set on exactly one plan; the selector opens on it. */
  default?: boolean;
  /** Optional flash, e.g. "Best value". Null means no badge. */
  badge?: string;
  /**
   * A single charge rather than a subscription.
   *
   * The programme is twelve weeks and then it is over, so paying in full buys
   * the whole thing outright — there is no week thirteen to renew into. It is
   * also the promise this audience cares about most, and a subscription cannot
   * make it: Checkout would say "every 12 weeks" at the moment she decides
   * whether to trust us, whatever we cancel afterwards.
   */
  oneTime?: boolean;
  /**
   * How many charges the twelve weeks take on this plan.
   *
   * A fact about the plan, not a slogan: weekly is twelve payments and
   * four-weekly is three, which is what `fulfil.ts` schedules the subscription
   * to stop after and what Checkout is told to say. Absent when she pays once.
   */
  instalments?: number;
  /**
   * Days of free trial before the first charge, absent for no trial.
   *
   * A trial plan is a *subscription* even when it takes one payment —
   * `mode: payment` cannot trial — so `oneTime` stays false and the single
   * charge is enforced by `fulfil.ts` scheduling `cancel_at` on the exact
   * boundary where the second period would begin (trial_end + 84 days).
   */
  trialDays?: number;
  /**
   * The line under "FiftyStrong" on the Stripe Checkout page.
   *
   * Per plan, because the promise is per plan: paying once is not "payments
   * stop after 12 weeks", it is that there was only ever one. Stripe hangs a
   * description off the *product*, so each plan carries its own product — see
   * `scripts/sync-stripe-catalog.ts`.
   */
  checkoutDescription: string;
}

/**
 * The Stripe product all three prices hang off.
 *
 * The description is the only sentence of ours Stripe will render beside the
 * price on the Checkout page, so it carries the promise that matters most —
 * and it has to be true of all three plans, because they share one product.
 * `custom_text` says the plan-specific version above the pay button.
 *
 * Kept here rather than typed into the Dashboard so that test and live cannot
 * drift; `pnpm sync-stripe-catalog` is what writes it.
 */
export const PRODUCT = {
  /**
   * The same for every plan. What differs is the line beneath it, which is
   * each plan's `checkoutDescription`.
   *
   * Kept here rather than typed into the Dashboard so that test and live cannot
   * drift; `pnpm sync-stripe-catalog` is what writes it.
   */
  name: "FiftyStrong",
} as const;

