 * `planForLookupKey` to translate and nothing mid-instalment to keep
 * billing. They stay unsold in Stripe rather than being archived here —
 * the sync script never deletes, and an unsellable price costs nothing. */
export const ALL_PLANS: Plan[] = [
  ...PLANS,
  ...FOUNDING69_PLANS,
  ...FOUNDING49_PLANS,
  ...TRIAL49_PLANS,
  /* Only the $59 trial is new here: trial59's pay-today option deliberately
     reuses founding49's live `fiftystrong_f49_12week` price, so the catalogue
     gains exactly one price rather than a duplicate $49 one. */
  ...TRIAL59_PLANS.filter((p) => p.id === "trial"),
  ...MONTHLY_PLANS,
];

export function getPlan(
  id: string,
  variant: keyof typeof PLAN_LADDERS = "control",
): Plan | undefined {
  return PLAN_LADDERS[variant].find((p) => p.id === id);
}

export function defaultPlan(
  variant: keyof typeof PLAN_LADDERS = "control",
): Plan {
  const d = PLAN_LADDERS[variant].find((p) => p.default);
  if (!d) throw new Error("no default plan configured");
  return d;
}

/**
 * The plan behind a Stripe lookup key, whichever arm sold it.
 *
 * The webhook and fulfilment both translate a line item back to a plan id;
 * searching only one ladder there would misreport every variant purchase.
 */
export function planForLookupKey(lookupKey: string): Plan | undefined {
  return ALL_PLANS.find((p) => p.lookupKey === lookupKey);
}

