/* FNV-1a, 32-bit. The multiply is spelled as shift-adds so the arithmetic is
 * identical in this file and the page's ES5 copy — `Math.imul` rounds the same
 * way but is one more thing the two copies could disagree on. */
function fnv1a(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
