/** The programme is twelve weeks and then it is over. Everything ends here. */
const TERM_DAYS = TOTAL_WEEKS * 7;
const DAY_SECONDS = 86_400;

/**
 * Make an instalment plan stop when the programme does.
 *
 * Weekly is twelve payments, four-weekly is three, and after that the twelve
 * weeks are paid for — there is no week thirteen to sell her. Stripe cannot
 * express this on the Checkout page (`subscription_data[cancel_at]` is not a
 * parameter on any API version we tried), so it is set here on the
 * subscription itself, the moment it exists.
 *
 * Anchored to the subscription's own timeline rather than the clock, so a
 * webhook retried an hour later computes the same instant and writes nothing
 * new. An existing `cancel_at` is left alone: it means either this already ran,
 * or she cancelled early from the billing portal, and both are her end date.
 *
 * The twelve paid weeks start when money starts: at `trial_end` for the trial
 * plan, at `start_date` otherwise. Counting a trial's term from its start_date
 * would land `cancel_at` *inside* the single paid period, and Stripe then
 * prorates the one charge below the advertised $49 — caught by
 * `scripts/verify-trial-billing.ts`, which is the proof this stays true.
 * From trial_end, cancel_at falls exactly on the period boundary: the full
 * $49 is charged, and the would-be second invoice is a cancellation instead.
 */
async function endWhenTheProgrammeDoes(
  subscription: Stripe.Subscription,
): Promise<Stripe.Subscription> {
  if (subscription.cancel_at) return subscription;
  const termStart = subscription.trial_end ?? subscription.start_date;
  return getStripe().subscriptions.update(subscription.id, {
    cancel_at: termStart + TERM_DAYS * DAY_SECONDS,
  });
}

