async function byInstalments(session: Stripe.Checkout.Session) {
  const subscriptionId = idOf(session.subscription);
  if (!subscriptionId) {
    throw new Error(`Checkout session ${session.id} has no subscription`);
  }

  // Always re-read the subscription rather than trusting whatever the session
  // was carrying: by the time a webhook is retried, the status may have moved
  // on, and a stale cache here decides whether she can train.
  const subscription = await getStripe().subscriptions.retrieve(subscriptionId);
  return cacheFrom(await endWhenTheProgrammeDoes(subscription));
}

