export async function recordPurchase(facts: PurchaseFacts): Promise<void> {
  const {
    personId,
    quizPublicId,
    created,
    plan,
    priceUsd,
    pricingVariant,
    emphasis,
    mode,
    userAgent,
    stripeCustomerId,
    stripeSubscriptionId,
    displayName,
    trialStart,
  } = facts;

  // Always. Idempotent, and the thing that makes her whole timeline one person.
  if (quizPublicId) {
    await aliasQuizToPerson(personId, quizPublicId);
  }

  // Pointers between systems, so any starting point reaches any other in one
  // hop: a Stripe dispute resolves to her quiz journey, a replay to her billing.
  await identifyServer(personId, {
    name: displayName ?? null,
    quiz_public_id: quizPublicId ?? null,
    plan: plan ?? null,
    // The arm as a person property too — client identify sets it at email
    // capture, but the woman who pays from a fresh device must not lose it.
    pricing_variant: pricingVariant ?? null,
    emphasis: emphasis ?? null,
