const stripe = new Stripe(key);

/** Marks the product as ours, so a renamed product is still found. */
const MARKER = { fiftystrong: "programme" };

/** What this plan's price must look like in Stripe. */
function recurringFor(plan: Plan): Stripe.PriceCreateParams.Recurring | undefined {
  if (plan.oneTime) return undefined;
  if (plan.renewal) return { interval: plan.renewal.interval, interval_count: plan.renewal.every };
  // Every instalment plan bills in whole weeks; the count is the term divided
  // by the number of payments, which `plans.test.ts` pins at twelve weeks.
  return { interval: "week", interval_count: 12 / (plan.instalments ?? 1) };
}

function matches(price: Stripe.Price, plan: Plan): boolean {
  if (price.unit_amount !== plan.amountCents) return false;
  if (price.currency !== plan.currency) return false;
  /* The euro amount rides on the same price object. A price carrying the
     wrong euro figure — or none — is as wrong as one carrying the wrong
     dollar figure, and far easier to miss, so it fails the match and gets
     replaced rather than being quietly left behind. */
  const eur = price.currency_options?.eur;
  if (!eur || eur.unit_amount !== plan.amountEurCents) return false;
  /* A price left on `unspecified` is rejected by any session with automatic
     tax on, so an existing one has to be replaced rather than kept. */
  if (price.tax_behavior !== "inclusive") return false;
  const want = recurringFor(plan);
  if (!want) return price.recurring === null;
  return (
    price.recurring?.interval === want.interval &&
    price.recurring?.interval_count === want.interval_count
  );
}

/**
 * The product this plan's price hangs off — one per *promise*.
 *
 * Stripe attaches a description to the *product*, not the price, and the
 * promise differs per plan: "payments stop after 12 weeks" is meaningless on
 * the plan where there is only ever one payment. So each plan owns a product,
 * identically named, carrying its own line.
 *
 * The trial plan shares its `twelve_week` id with the buy-now plans — same
 * fulfilment — but its promise ("7 days free, then…") is its own. Keying
 * products by bare plan id would make the arms fight over one product's
 * description, last-synced arm winning on every ladder's Checkout page; the
 * key therefore carries the trial-ness.
 */
function productKeyFor(plan: Plan): string {
  /* One product per *promise*, which is why arms sharing a plan id share a
     product: control's weekly and founding49's weekly both say "12 weekly
     payments", so one description serves both.

     The instalment count is part of the promise, though. Both arms sell a
     `trial` plan, but one is "7 days free, then one payment" and the other
     "7 days free, then 3 payments" — keying on id alone collided them onto a
     single product, and whichever synced last silently rewrote the other's
     description on the Checkout page. */
  const trial = plan.trialDays ? "_trial" : "";
  const n = plan.instalments ?? 1;
  return `${plan.id}${trial}${n > 1 ? `_x${n}` : ""}`;
}

async function productFor(plan: Plan): Promise<Stripe.Product> {
  const write = (id: string) =>
    stripe.products.update(id, {
      name: PRODUCT.name,
      description: plan.checkoutDescription,
      metadata: { ...MARKER, plan: productKeyFor(plan) },
    });

  /*
   * Whatever this plan's current price already hangs off — but only if that
   * product belongs to this plan.
   *
   * Deliberately not `products.search`: that index is eventually consistent, so
   * a product created seconds ago is not found, and an earlier version of this
   * script built a second product on every run because of it. `prices.list` by
   * lookup key is strongly consistent and is the same lookup checkout uses.
   *
   * The ownership check is what migrates a catalogue where every plan shared
   * one product: the shared product fails it, so each plan gets its own and
   * the price is rebuilt onto it.
   */
  const { data } = await stripe.prices.list({
    lookup_keys: [plan.lookupKey],
    active: true,
    expand: ["data.product"],
  });

