async function main() {
  console.log(`\nStripe catalogue → ${live ? "LIVE" : "test"} mode\n`);

  // Both arms of the pricing experiment; each plan id's two prices share
  // one product (same name, same promise — only the amount differs).
  for (const plan of ALL_PLANS) {
    const product = await productFor(plan);
    const { data } = await stripe.prices.list({
      lookup_keys: [plan.lookupKey],
      active: true,
    });
    const current = data[0];

    if (current && matches(current, plan) && current.product === product.id) {
      console.log(
        `  ${plan.lookupKey.padEnd(22)} ${current.id}  unchanged  (${product.id})`,
      );
      continue;
    }

    // New price first, lookup key moved onto it in the same call, old one
    // archived after — so there is no instant where the key resolves to
    // nothing and checkout fails.
    const fresh = await stripe.prices.create({
      product: product.id,
      unit_amount: plan.amountCents,
      currency: plan.currency,
      /* Same number, not a conversion: €49, never €45.31. Both live on one
         price object so a single lookup key serves both currencies and there
         is no parallel catalogue to drift. */
      currency_options: { eur: { unit_amount: plan.amountEurCents } },
      /*
       * The advertised figure already contains any tax.
       *
       * Stated on the price rather than left to the account default, because
       * the two accounts disagree: test mode defaults to
       * `inferred_by_currency`, live mode's default is null — and a price with
       * no tax behaviour is REJECTED outright by a session with
       * `automatic_tax` enabled. That difference would have surfaced as live
       * checkout failing for every buyer while test passed.
       *
       * Inclusive, not exclusive, because €49 has to stay €49 on the paywall:
       * an EU consumer price is quoted tax-in. Once a registration exists the
       * VAT comes out of the 49, it is not added on top — which is the same
       * arithmetic as owing it unregistered, just collected properly.
       */
      tax_behavior: "inclusive" as const,
      ...(recurringFor(plan) ? { recurring: recurringFor(plan) } : {}),
      lookup_key: plan.lookupKey,
      transfer_lookup_key: true,
    });
    if (current) await stripe.prices.update(current.id, { active: false });

    console.log(
      `  ${plan.lookupKey.padEnd(22)} ${fresh.id}  ${current ? `replaces ${current.id}` : "created"}` +
        `  → ${(plan.amountCents / 100).toFixed(2)} ${plan.currency}` +
        ` / ${(plan.amountEurCents / 100).toFixed(2)} eur` +
        `${plan.oneTime ? " one-off" : ` every ${recurringFor(plan)!.interval_count} ${recurringFor(plan)!.interval}(s)`}`,
    );
  }

  console.log(
    "\nDone. Run `pnpm test:stripe` to assert the paywall's numbers against these.\n",
  );
}

